INSERT INTO movie_film (title, synopsis, pic, region, director, release_date, times, score, grade, category, profit, organization, created) VALUES
('西虹市首富', '在特烦恼之城的西虹市，混迹于丙级业余足球队的守门员王多鱼（沈腾饰），因比赛失利被开除离队。正处于人生最低谷的他接受了神秘台湾财团一个月花光十亿资金的挑战。本以为快乐生活就此开始，王多鱼却第一次感到“花钱特烦恼”。想要人生反转走上巅峰，真的没有那么简单...', NULL, 1, '闫非、彭大魔', '2018-07-27', 9180, 8.9, 'PG-13', 2, 254759, '北京开心麻花影业有限公司', NOW()),
('流浪地球', '在并不遥远的未来，太阳急速衰老与膨胀，再过几百年整个太阳系将被它吞噬毁灭。为了应对这场史无前例的危机，地球各国放下芥蒂，成立联合政府，试图寻找人类存续的出路。通过摸索与考量，推着地球逃出太阳的“移山计划”获得压倒性胜利。人们着手建造上万台巨大的行星发动机，带着地球踏上漫漫征程。满腔赤诚的刘培强和韩子昂历经层层考验成为航天员大队的一员，并由此相知相恋。但是漫漫征途的前方，仿佛有一股神秘的力量不断破坏者人类的自救计划。看似渺小的刘启、朵朵、王磊、周倩、Tim等人，构成了这项伟大计划的重要一环...', NULL, 1, '郭帆', '2019-02-05', 8520, 9.3, 'PG-13', 8, 468875, '中国电影股份有限公司', NOW()),
('哪吒之魔童降世', '天劫降临，哪吒即将面对人生最大的考验。天地灵气孕育出一颗能量巨大的混元珠，元始天尊将混元珠提炼成灵珠和魔丸，灵珠投胎为人，助周伐纣时可堪大用；而魔丸则会诞出魔王，为祸人间。元始天尊启动了天劫咒语，3年后天雷将会降临，摧毁魔丸。太乙真人受命将灵珠托生于陈塘关李靖家的儿子哪吒身上。然而阴差阳错，灵珠和魔丸竟然被掉包。本应是灵珠英雄的哪吒却成了混世大魔王。调皮捣蛋顽劣不堪的哪吒却徒有一颗做英雄的心。然而面对众人对魔丸的误解和即将来临的天雷的降临，哪吒是否命中注定会立地成魔？他将何去何从？', NULL, 1, '饺子', '2019-07-26', 7200, 9.4, 'PG', 4, 503541, '可可豆动画影视有限公司', NOW()),
('复仇者联盟4：终局之战', '一声响指，宇宙间半数生命灰飞烟灭。几近绝望的复仇者们在惊奇队长的帮助下找到灭霸归隐之处，却得知六颗无限宝石均被销毁，希望彻底破灭。如是过了五年，迷失在量子领域的斯科特意外回到现实世界，他的出现为幸存的复仇者们点燃了希望。与美国队长、黑寡妇等人商议后，他们决定回到过去，集齐无限宝石，试图逆转灭霸的所作所为。', NULL, 3, '安东尼·罗素、乔·罗素', '2019-04-24', 9600, 9.0, 'PG-13', 8, 425000, '漫威影业', NOW()),
('疯狂动物城', '故事发生在一个所有哺乳类动物和谐共存的美好城市中，兔子朱迪从小就梦想着能够成为一名惩恶扬善的刑警，凭借着智慧和努力，朱迪成功的从警校中毕业进入了疯狂动物城警察局，殊不知这里是大型肉食类动物的领地，作为第一只，也是唯一的小型食草类动物，朱迪会遇到怎样的故事呢？', NULL, 3, '拜恩·霍华德、里奇·摩尔', '2016-03-04', 6660, 9.2, 'G', 4, 153000, '华特迪士尼影业', NOW()),
('泰坦尼克号', '1912年4月10日，号称“世界工业史上的奇迹”的豪华客轮泰坦尼克号开始了自己的处女航，从英国的南安普顿出发驶往美国纽约。富家少女罗丝与母亲及未婚夫卡尔坐上了头等舱；另一边，放荡不羁的少年画家杰克也在码头的一场赌博中赢得了下等舱的船票。', NULL, 3, '詹姆斯·卡梅隆', '1998-04-03', 9900, 9.5, 'PG-13', 5, 186000, '二十世纪福克斯', NOW()),
('霸王别姬', '段小楼与程蝶衣是一对打小一起长大的师兄弟，两人一个演生，一个饰旦，一向配合天衣无缝，尤其一出《霸王别姬》，更是誉满京城，为此，两人约定合演一辈子《霸王别姬》。但两人对戏剧与人生关系的理解有本质不同，段小楼深知戏非人生，程蝶衣则是人戏不分。', NULL, 1, '陈凯歌', '1993-01-01', 7200, 9.6, 'NC-17', 5, 4000, '北京电影制片厂', NOW()),
('千与千寻', '10岁的少女千寻与父母一起从都市搬家到了乡下。没想到在搬家的途中，一家人发生了意外。他们进入了汤屋老板魔女控制的奇特世界——在那里不劳动的人将会被变成动物。千寻的父母因贪吃变成了猪，千寻为了救父母经历了很多磨难。', NULL, 4, '宫崎骏', '2001-07-20', 6600, 9.4, 'G', 4, 30000, '吉卜力工作室', NOW()),
('肖申克的救赎', '一场谋杀案使银行家安迪蒙冤入狱，在监狱的岁月里，他结识了瑞德。在监狱里，安迪凭借自己的智慧和毅力，不仅让自己获得了生存的空间，还暗中为自己的未来铺路。最终，他成功逃出了监狱，获得了自由。', NULL, 3, '弗兰克·德拉邦特', '1994-09-23', 8580, 9.7, 'R', 5, 2834, '哥伦比亚影业', NOW()),
('阿甘正传', '阿甘是个智商只有75的低能儿。在学校里为了躲避别的孩子的欺侮，听从一个朋友珍妮的话而开始"跑"。他跑着躲避别人的捉弄。在中学时，他为了躲避别人而跑进了一所学校的橄榄球场，就这样跑进了大学。阿甘被破格录取，并成了橄榄球巨星，受到了肯尼迪总统的接见。', NULL, 3, '罗伯特·泽米吉斯', '1994-07-06', 8220, 9.5, 'PG-13', 5, 67794, '派拉蒙影业', NOW()),
('盗梦空间', '道姆·柯布是一名专门从事意识深层盗窃的高手，他能够潜入人们梦境中盗取机密。但是，他的目标是完成一次"植入"任务，即在目标的潜意识中植入一个想法。这是一项几乎不可能完成的任务，但柯布决定尝试。', NULL, 3, '克里斯托弗·诺兰', '2010-09-01', 8640, 9.3, 'PG-13', 8, 83000, '华纳兄弟影业', NOW()),
('星际穿越', '在不远的未来，地球环境恶化，人类面临生存危机。宇航员库珀穿越虫洞寻找适合人类居住的新家园。在这个过程中，他经历了时间的扭曲和亲情的考验。', NULL, 3, '克里斯托弗·诺兰', '2014-11-07', 9900, 9.4, 'PG-13', 8, 75500, '派拉蒙影业', NOW()),
('红海行动', '索马里海域外，中国商船遭遇劫持，船员全数沦为阶下囚。蛟龙突击队沉着应对，潜入商船进行突袭，成功解救全部人质。返航途中，非洲北部伊维亚共和国发生政变，恐怖组织连同叛军攻入首都，当地华侨面临危险。海军战舰接到上级命令改变航向，前往执行撤侨任务。', NULL, 1, '林超贤', '2018-02-16', 7920, 9.0, 'PG-13', 1, 365000, '博纳影业', NOW()),
('战狼2', '在非洲附近的大海上，主人公冷锋遭遇人生滑铁卢，被"开除军籍"。一场突如其来的意外打破了他的计划，突然被卷入了一场非洲国家叛乱。', NULL, 1, '吴京', '2017-07-27', 7860, 8.5, 'PG-13', 1, 569000, '北京登峰国际文化传播有限公司', NOW()),
('飞驰人生', '曾经在赛车界叱咤风云、如今却只能经营炒饭大排档的赛车手张驰决定重返车坛挑战年轻一代的天才。然而没钱没车没队友，甚至驾照都得重新考。', NULL, 1, '韩寒', '2019-02-05', 6720, 8.2, 'PG', 2, 171764, '上海亭东影业有限公司', NOW()),
('唐人街探案3', '继曼谷、纽约之后，东京再出大案。唐人街神探唐仁、秦风受侦探野田昊的邀请前往破案。"CRIMASTER世界侦探排行榜"中的侦探们闻讯后也齐聚东京，加入挑战，而排名第一Q的现身，让这个大案更加扑朔迷离，一场亚洲最强神探之间的较量即将爆笑展开...', NULL, 1, '陈思诚', '2021-02-12', 7800, 7.2, 'PG-13', 2, 452365, '万达影视传媒有限公司', NOW()),
('蜘蛛侠：英雄远征', '在经历了复仇者联盟终局之战后，彼得·帕克回到了高中生活。他想暂时远离超级英雄的身份，好好享受一次欧洲之旅。但是，尼克·弗瑞的突然出现打乱了他的计划。', NULL, 3, '乔·沃茨', '2019-07-02', 6600, 8.5, 'PG-13', 8, 115000, '漫威影业', NOW()),
('速度与激情：特别行动', '一个是美国外交安全局的忠诚特工霍布斯，一个是前英国军事特工精英肖，两人本是不共戴天的宿敌。但在面对更强大的敌人布里克斯顿时，他们不得不联手。', NULL, 3, '大卫·雷奇', '2019-08-23', 6480, 7.8, 'PG-13', 1, 143000, '环球影业', NOW()),
('寄生虫', '基宇出生在一个贫穷的家庭，全家都在半地下室里生活。他的朋友给他介绍了一个给富裕家庭当家教的机会。基宇一家人渐渐融入了这个富裕家庭的生活，但他们的秘密也逐渐暴露。', NULL, 4, '奉俊昊', '2019-05-30', 7320, 9.0, 'R', 5, 20000, 'Barunson E&A', NOW()),
('釜山行', '在一次偶然发生的交通事故后，被撞倒死掉的野猪感染了病毒，韩国某城市的市民开始变得奇怪起来。为了掩盖这种情况，政府部门封锁了消息。石宇是一个工作繁忙的基金经理，他的妻子已经去世，他和女儿秀安一起生活。', NULL, 4, '延相昊', '2016-07-20', 6060, 8.5, 'NC-17', 6, 9300, 'Next Entertainment World', NOW());
